79	    /**
80	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
81	     * domain containing at least one dot, with no whitespace in any part.
82	     */
83	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
84	
85	    /**
86	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email domain
87	     * (the part after the {@code @}, compared case-insensitively) is listed here is rejected: such
88	     * addresses are not durable contact details. Entries are stored lower-cased.
89	     */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
91	        "mailinator.com",
92	        "tempmail.com",
93	        "guerrillamail.com");
94	
95	    /**
96	     * Dedicated audit logger. On a successful owner create two records are emitted here: a
97	     * human-readable audit line carrying the new owner's id, member id, registration date and
98	     * membership level, and — separately — an immutable structured {@code OWNER_CREATED} event
99	     * ({@link OwnerCreatedEvent}) serialized as JSON.
100	     */
101	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
102	
103	    /**
104	     * Dedicated notification logger. On a successful owner create a welcome notification is enqueued
105	     * here: a single line carrying the new owner's id and member id.
106	     */
107	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
108	
109	    /**
110	     * Serializer for the structured {@code OWNER_CREATED} audit event. A record's components are
111	     * emitted in declaration order, giving the event a stable field layout.
112	     */
113	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
114	
115	    /**
116	     * Monotonically increasing sequence stamped onto each structured {@code OWNER_CREATED} event. It
117	     * advances by one per emitted event across all creates for the application's lifetime, giving the
118	     * audit stream a total order independent of owner ids or timestamps.
119	     */
120	    private static final AtomicInteger OWNER_CREATED_SEQ = new AtomicInteger(0);
121	
122	    /**
123	     * Common street-type abbreviations expanded during address normalization. Keys are the
124	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
125	     * expanded form it is replaced with.
126	     */
127	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
128	        "ST", "STREET",
129	        "RD", "ROAD",
130	        "AVE", "AVENUE");
131	
132	    /**
133	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
134	     * is at capacity and cannot take any more.
135	     */
136	    private static final int CITY_CAPACITY = 50;
137	
138	    /**
139	     * The number of owners a city must already hold before a response starts carrying a
140	     * {@code capacityWarning}. Once a city holds at least this many owners (but still fewer than the
141	     * hard {@link #CITY_CAPACITY} limit), it is flagged as approaching capacity.
142	     */
143	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
144	
145	    /**
146	     * The maximum number of owners that may be registered in a single day. Once this many owners
147	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
148	     * owners can be created that day.
149	     */
150	    private static final int DAILY_OWNER_LIMIT = 100;
151	
152	    /**
153	     * The number of owners that may be registered on a single business day before a response starts
154	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
155	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
156	     * high volume.
157	     */
158	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
159	
160	    /**
161	     * Fixed public holidays that the business-day roll skips over. A registration date that lands on
162	     * one of these dates is rolled forward to the next non-holiday business day, exactly as a weekend
163	     * date is rolled forward off a Saturday or Sunday.
164	     */
165	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
166	        LocalDate.parse("2026-01-01"),
167	        LocalDate.parse("2026-01-26"),
168	        LocalDate.parse("2026-04-25"),
169	        LocalDate.parse("2026-12-25"),
170	        LocalDate.parse("2026-12-28"));
171	
172	    /**
173	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
174	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
175	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
176	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
177	     */
178	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
179	        "61", 9,
180	        "1", 10);
181	
182	    /**
183	     * Fixed region-to-postcode-range lookup used both to validate an owner's optional postcode against
184	     * the region derived from the owner's city ({@link #regionForCity}) and to derive the postcode's own
185	     * region for the {@code memberId} ({@link #regionForPostcode}). Each value is the inclusive
186	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
187	     * region that is not listed ({@code 'UNKNOWN'}) carries no range and accepts any 4-digit postcode.
188	     */
189	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
190	        "NSW", new int[] {2000, 2099},
191	        "VIC", new int[] {3000, 3099},
192	        "QLD", new int[] {4000, 4099});
193	
194	    /**
195	     * Fixed city-to-region lookup used to validate an owner's optional postcode against the region
196	     * derived from the owner's city. Any city not listed has region {@code 'UNKNOWN'} and so accepts
197	     * any 4-digit postcode.
198	     */
199	    private static final Map<String, String> CITY_REGION = Map.of(
200	        "Sydney", "NSW",
201	        "Melbourne", "VIC",
202	        "Brisbane", "QLD");
203	
204	    /**
205	     * Remembers the owner created for each {@code Idempotency-Key} seen on a create request, keyed by
206	     * the header value. A repeated create carrying a key already present here is served the originally
207	     * created owner instead of creating a duplicate, so retries are safe. The map only ever grows with
208	     * distinct keys and is held for the application's lifetime, consistent with the in-memory, single
209	     * instance scope of this sample.
210	     */
211	    private final Map<String, Integer> idempotentCreateOwnerIds = new ConcurrentHashMap<>();
