260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
263	        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
264	        if (replay != null) {
265	            return replay;
266	        }
267	        validateRequiredFields(ownerFieldsDto);
268	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
269	        LocalDate registrationDate = toBusinessDay(
270	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
271	        rejectDailyLimitReached(registrationDate);
272	        HttpHeaders headers = new HttpHeaders();
273	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
274	        applyAddress(owner, ownerFieldsDto);
275	        rejectCityAtCapacity(owner.getCity());
276	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
277	        owner.setTelephone(telephone);
278	        String email = normalizeEmail(ownerFieldsDto.getEmail());
279	        owner.setEmail(email);
280	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), regionForCity(owner.getCity())));
281	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
282	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
283	        rejectDuplicateIdentity(owner);
284	        applyPossibleDuplicate(owner, sharesHousehold);
285	        owner.setRegistrationDate(registrationDate);
286	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
287	        owner.setMemberId(generateMemberId(owner.getPostcode(), owner.getTelephone(),
288	            owner.getLastName(), owner.getRegistrationDate()));
289	        owner.setMembershipLevel(cappedMembershipLevel(owner));
290	        this.clinicService.saveOwner(owner);
291	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
292	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
293	            owner.getMembershipLevel());
294	        emitOwnerCreatedEvent(owner);
295	        enqueueWelcomeNotification(owner);
296	        rememberIdempotentCreate(idempotencyKey, owner.getId());
297	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
298	        applyBulkSignupWarning(ownerDto);
299	        applyCapacityWarning(ownerDto);
300	        applyRiskFlag(ownerDto);
301	        headers.setLocation(UriComponentsBuilder.newInstance()
302	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
303	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
304	    }
305	
306	    /**
307	     * Serves a repeated create that carries an {@code Idempotency-Key} already seen on an earlier
308	     * successful create. When the key has a remembered owner that still exists, the originally created
309	     * owner is returned with {@code 200 OK} (carrying its {@code Location}) so the retry neither creates
310	     * a duplicate nor re-runs the create rules. A {@code null} or blank key, an unseen key, or a key
311	     * whose owner no longer exists yields {@code null}, signalling the caller to perform a normal create.
312	     *
313	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
314	     * @return the originally created owner as a {@code 200 OK} response, or {@code null} to create normally
315	     */
316	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
317	        if (isBlank(idempotencyKey)) {
318	            return null;
319	        }
320	        Integer ownerId = idempotentCreateOwnerIds.get(idempotencyKey);
321	        if (ownerId == null) {
322	            return null;
323	        }
324	        Owner owner = this.clinicService.findOwnerById(ownerId);
325	        if (owner == null) {
326	            return null;
327	        }
328	        HttpHeaders headers = new HttpHeaders();
329	        headers.setLocation(UriComponentsBuilder.newInstance()
330	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
331	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
332	        applyBulkSignupWarning(ownerDto);
333	        applyCapacityWarning(ownerDto);
334	        applyRiskFlag(ownerDto);
335	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.OK);
336	    }
337	
338	    /**
339	     * Remembers the owner just created under its request's {@code Idempotency-Key}, so a later create
340	     * repeating that key is served the same owner ({@link #replayIdempotentCreate}). A {@code null} or
341	     * blank key is ignored, leaving that create non-idempotent.
342	     *
343	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
344	     * @param ownerId        the id of the owner that was just created
345	     */
346	    private void rememberIdempotentCreate(String idempotencyKey, Integer ownerId) {
347	        if (!isBlank(idempotencyKey)) {
348	            idempotentCreateOwnerIds.put(idempotencyKey, ownerId);
349	        }
350	    }
351	
352	    /**
353	     * Emits the immutable structured {@code OWNER_CREATED} event for a freshly created owner on the
354	     * {@code AUDIT} logger, serialized as a JSON object {@code {seq, ownerId, memberId,
355	     * membershipLevel, event}}. The {@code seq} is drawn from {@link #OWNER_CREATED_SEQ}, advancing by
356	     * one per create so the events carry a total order. The {@code memberId} field carries the owner's
357	     * current primary identifier ({@link #primaryIdentifier}) — the unified member id.
358	     *
359	     * @param owner the owner that was just created and saved
360	     */
361	    private void emitOwnerCreatedEvent(Owner owner) {
362	        OwnerCreatedEvent event = new OwnerCreatedEvent(
363	            OWNER_CREATED_SEQ.incrementAndGet(),
364	            owner.getId(),
365	            primaryIdentifier(owner),
366	            owner.getMembershipLevel());
367	        AUDIT.info("{}", AUDIT_MAPPER.writeValueAsString(event));
368	    }
369	
370	    /**
371	     * Enqueues a welcome notification for a freshly created owner by emitting a single line on the
372	     * {@code NOTIFY} logger carrying the new owner's id and member id.
373	     *
374	     * @param owner the owner that was just created and saved
375	     */
376	    private void enqueueWelcomeNotification(Owner owner) {
377	        NOTIFY.info("Welcome notification: ownerId={} memberId={}",
378	            owner.getId(), primaryIdentifier(owner));
379	    }
380	
381	    /**
382	     * Returns the owner's current primary identifier — the single value that externally names the
383	     * owner and is carried by the structured audit event. That is the unified {@code memberId}; this
384	     * is the one place to change should a later evolution replace it, so every consumer of the primary
385	     * identifier follows automatically.
386	     *
387	     * @param owner the owner whose primary identifier is wanted
388	     * @return the owner's current primary identifier
389	     */
390	    private String primaryIdentifier(Owner owner) {
391	        return owner.getMemberId();
392	    }
393	
394	    /**
395	     * Immutable structured audit event emitted on a successful owner create. Serialized to JSON on the
396	     * {@code AUDIT} logger, its component order fixes the field order {@code {seq, ownerId, memberId,
397	     * membershipLevel, event}}. The {@code event} discriminator is always {@code 'OWNER_CREATED'}. The
398	     * {@code memberId} component holds the owner's current primary identifier
399	     * ({@link #primaryIdentifier}) — the unified member id.
400	     *
401	     * @param seq             monotonically increasing sequence across all creates
402	     * @param ownerId         the new owner's id
403	     * @param memberId        the owner's current primary identifier
404	     * @param membershipLevel the owner's stored membership level
405	     */
406	    private record OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel,
407	                                     String event) {
408	        private OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel) {
409	            this(seq, ownerId, memberId, membershipLevel, "OWNER_CREATED");
410	        }
411	    }
