508	    /**
509	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
510	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
511	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
512	     *
513	     * @param ownerFieldsDto the submitted owner fields
514	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
515	     *                                     name of every offending field
516	     */
517	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
518	        List<String> missingFields = new ArrayList<>();
519	        if (isBlank(ownerFieldsDto.getFirstName())) {
520	            missingFields.add("firstName");
521	        }
522	        if (isBlank(ownerFieldsDto.getLastName())) {
523	            missingFields.add("lastName");
524	        }
525	        if (!hasAddress(ownerFieldsDto)) {
