602	    /**
603	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
604	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
605	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
606	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
607	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
608	     *
609	     * @param telephone the raw telephone value submitted by the client
610	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
611	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
612	     *                                     400 response
613	     */
614	    private String normalizeTelephone(String telephone) {
615	        String e164 = toE164(telephone);
616	        if (e164 == null) {
617	            throw new InvalidOwnerFieldsException(List.of("telephone"));
618	        }
619	        return e164;
