622	    /**
623	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
624	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
625	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
626	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
627	     * and when the supplied country code is one with a known national-number length
628	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
629	     * number must have exactly that many digits.
630	     *
631	     * @param telephone the raw telephone value, possibly {@code null}
632	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
633	     */
634	    private String toE164(String telephone) {
635	        if (telephone == null) {
636	            return null;
637	        }
638	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
639	        boolean hasPlus = cleaned.startsWith("+");
640	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
641	        String nationalSignificant = hasPlus
642	            ? digits
643	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
644	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
645	            return null;
646	        }
647	        if (!hasValidNationalNumberLength(nationalSignificant)) {
648	            return null;
649	        }
650	        return "+" + nationalSignificant;
651	    }
652	
653	    /**
654	     * Checks the national-number length of an E.164 number (country code plus national significant
655	     * digits, no leading {@code '+'}) against the per-country requirement in
656	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
657	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
658	     * country code is not listed carries no per-country length requirement and is accepted.
659	     *
660	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
661	     *                            leading {@code '+'}
662	     * @return {@code true} if the national-number length is correct for the country code, or the
663	     *         country code has no listed requirement; {@code false} otherwise
664	     */
665	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
666	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
667	            .filter(nationalSignificant::startsWith)
668	            .max(Comparator.comparingInt(String::length))
669	            .orElse(null);
670	        if (countryCode == null) {
671	            return true;
672	        }
673	        int nationalLength = nationalSignificant.length() - countryCode.length();
674	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
675	    }
