723	    /**
724	     * Builds the owner's {@code memberId}, formatted {@code '<REGION><FY><HASH8><CHK>'} with no
725	     * separators, unifying the former customer code and membership number into a single value.
726	     * {@code REGION} is the region code derived from the owner's postcode ({@link #regionForPostcode},
727	     * {@code 'UNKNOWN'} when the postcode is absent or in no known range); {@code FY} is the two-digit
728	     * fiscal year (which starts on 1 July) of the business-day-adjusted {@code registrationDate};
729	     * {@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the owner's
730	     * normalized telephone followed by the last name (the same segment used by the region-and-hash
731	     * identity); and {@code CHK} is a single Luhn check digit computed over the digits of
732	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW261A2B3C4D7'}). The identity carries no sequence
733	     * number, so the same postcode region, fiscal year, telephone and last name always yield the same
734	     * member id.
735	     *
736	     * <p>If the computed member id collides with an existing owner's {@code memberId}, it is
737	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
738	     * unique, so distinct owners always receive distinct member ids.
739	     *
740	     * @param postcode         the owner's validated postcode, or {@code null} if none was supplied
741	     * @param telephone        the owner's normalized (E.164) telephone
742	     * @param lastName         the owner's last name
743	     * @param registrationDate the owner's business-day-adjusted registration date
744	     * @return the formatted, de-duplicated member id
745	     */
746	    private String generateMemberId(String postcode, String telephone, String lastName, LocalDate registrationDate) {
747	        String region = regionForPostcode(postcode);
748	        String fy = String.format("%02d", FiscalYear.of(registrationDate) % 100);
749	        String hash8 = hashHex(telephone + lastName, 8);
750	        String prefix = region + fy + hash8;
751	        String baseId = prefix + luhnCheckDigit(prefix);
752	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
753	            .map(Owner::getMemberId)
754	            .filter(Objects::nonNull)
755	            .collect(Collectors.toSet());
756	        if (!existingIds.contains(baseId)) {
757	            return baseId;
758	        }
759	        int n = 2;
760	        while (existingIds.contains(baseId + "-" + n)) {
761	            n++;
762	        }
763	        return baseId + "-" + n;
764	    }
765	
766	    /**
767	     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value}. The standard
768	     * Luhn algorithm runs over the digits from right to left, doubling every second digit (subtracting
769	     * 9 when a doubled value exceeds 9); non-digit characters are skipped. This is the {@code <CHK>}
770	     * segment of a {@code memberId}, computed over the digits of its {@code <REGION><FY><HASH8>} prefix.
771	     *
772	     * @param value the value whose digits the check digit is computed over
773	     * @return the Luhn check digit, 0 to 9
774	     */
775	    private int luhnCheckDigit(String value) {
776	        int sum = 0;
777	        boolean dbl = true;
778	        for (int i = value.length() - 1; i >= 0; i--) {
779	            char c = value.charAt(i);
780	            if (c < '0' || c > '9') {
781	                continue;
782	            }
783	            int d = c - '0';
784	            if (dbl) {
785	                d *= 2;
786	                if (d > 9) {
787	                    d -= 9;
788	                }
789	            }
790	            sum += d;
791	            dbl = !dbl;
792	        }
793	        return (10 - (sum % 10)) % 10;
794	    }
