796	    /**
797	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
798	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
799	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
800	     * {@code <REGION>} segment baked into the {@code memberId}.
801	     *
802	     * @param postcode the owner's postcode, or {@code null}
803	     * @return the region code, or {@code 'UNKNOWN'}
804	     */
805	    private String regionForPostcode(String postcode) {
806	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
807	            return "UNKNOWN";
808	        }
809	        int value = Integer.parseInt(postcode);
810	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
811	            int[] range = entry.getValue();
812	            if (value >= range[0] && value <= range[1]) {
813	                return entry.getKey();
814	            }
815	        }
816	        return "UNKNOWN";
817	    }
