957	    /**
958	     * Reports whether an email address carries a disposable-adjacent domain: its domain (the part
959	     * after the last {@code @}, compared case-insensitively) is a subdomain of a listed disposable
960	     * mail provider ({@link #DISPOSABLE_EMAIL_DOMAINS}) — the lower-cased domain equals a listed
961	     * disposable domain or ends with {@code '.'} followed by one. Exact disposable domains are already
962	     * rejected at creation, so in practice this catches their subdomains, which slip past that
963	     * exact-match blocklist. A {@code null}, blank or address without a domain is not adjacent.
964	     *
965	     * @param email the owner's stored email address, or {@code null} if none
966	     * @return {@code true} if the email domain is disposable-adjacent
967	     */
968	    private boolean isDisposableAdjacentEmail(String email) {
969	        if (isBlank(email)) {
970	            return false;
971	        }
972	        int at = email.lastIndexOf('@');
973	        if (at < 0 || at == email.length() - 1) {
974	            return false;
975	        }
976	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
977	        return DISPOSABLE_EMAIL_DOMAINS.stream()
978	            .anyMatch(disposable -> domain.equals(disposable) || domain.endsWith("." + disposable));
979	    }
