1003	    /**
1004	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
1005	     * owner's. The identity key — the SHA-256 hex digest of {@code '<normalizedTelephone>|<lowerEmail>
1006	     * |<soundex(lastName)>'} — is the single value that consolidates all duplicate detection: the
1007	     * previously separate telephone, email and household checks are all expressed through it. Because
1008	     * the telephone is part of the key, two owners with the same last name and postcode but different
1009	     * telephones have different identity keys and are both allowed (the second is a soft match); only a
1010	     * whole-key match is a duplicate. The owner being created already carries its normalized telephone,
1011	     * email and last name, and existing owners store the same normalized forms, so the keys are
1012	     * compared directly. Owners flagged deleted are ignored.
1013	     *
1014	     * @param owner the owner being created, with its telephone, email and last name already set
1015	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
1016	     *                                         yielding a 409 Conflict response
1017	     */
1018	    private void rejectDuplicateIdentity(Owner owner) {
1019	        String identityKey = owner.getIdentityKey();
1020	        boolean inUse = this.clinicService.findAllOwners().stream()
1021	            .filter(this::isNotDeleted)
1022	            .map(Owner::getIdentityKey)
1023	            .anyMatch(identityKey::equals);
1024	        if (inUse) {
1025	            throw new DuplicateOwnerIdentityException(identityKey);
1026	        }
1027	    }
1028	
1029	    /**
1030	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
1031	     * that is not a hard duplicate (its identity key is unique, so it has already passed
1032	     * {@link #rejectDuplicateIdentity}) yet whose {@code soundex(lastName)} and postcode both match an
1033	     * existing owner's. Because the telephone is part of the identity key, two owners that share a last
1034	     * name and postcode but carry different telephones have different identity keys, so the second is
1035	     * created as a soft match rather than rejected. When such a match exists the owner is created with
1036	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
1037	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
1038	     * {@code false} and {@code possibleDuplicateOf} is left unset.
1039	     *
1040	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
1041	     * declared household member is not a suspected duplicate. An owner without a postcode cannot match
1042	     * on postcode and so is never flagged.
1043	     *
1044	     * @param owner           the owner being created, with its telephone, email, postcode and last
1045	     *                        name already set
1046	     * @param sharesHousehold whether the owner declared itself a member of an existing household
1047	     */
1048	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
1049	        owner.setPossibleDuplicate(false);
1050	        if (sharesHousehold) {
1051	            return;
1052	        }
1053	        String postcode = owner.getPostcode();
1054	        if (postcode == null) {
1055	            return;
1056	        }
1057	        String soundex = owner.getLastNameSoundex();
1058	        String identityKey = owner.getIdentityKey();
1059	        Owner match = this.clinicService.findAllOwners().stream()
1060	            .filter(this::isNotDeleted)
1061	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
1062	                && soundex.equals(existing.getLastNameSoundex())
1063	                && postcode.equals(existing.getPostcode()))
1064	            .min(Comparator.comparingInt(Owner::getId))
1065	            .orElse(null);
1066	        if (match != null) {
1067	            owner.setPossibleDuplicate(true);
1068	            owner.setPossibleDuplicateOf(match.getId());
1069	        }
1070	    }
1071	
1072	    /**
1073	     * Caps the membership level of the owner being created so it cannot exceed one above the current
1074	     * maximum membership level among its existing household members. A household member is a live (not
1075	     * soft-deleted) owner carrying the same computed {@code householdId}. The owner's own derived level
1076	     * ({@link Owner#getDerivedMembershipLevel()}) is returned capped at that maximum plus one; when the
1077	     * owner belongs to no household, or no existing household member is found, no cap applies and the
1078	     * derived level is returned unchanged. The owner being created has not been saved yet, so it is
1079	     * never considered its own household member.
1080	     *
1081	     * @param owner the owner being created, with its household id and level-affecting fields set
1082	     * @return the membership level to store, capped to the household ceiling where one exists
1083	     */
1084	    private Integer cappedMembershipLevel(Owner owner) {
1085	        int derivedLevel = owner.getDerivedMembershipLevel();
1086	        String householdId = owner.getHouseholdId();
1087	        if (householdId == null || householdId.isBlank()) {
1088	            return derivedLevel;
1089	        }
1090	        OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
1091	            .filter(this::isNotDeleted)
1092	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1093	            .mapToInt(Owner::getMembershipLevel)
1094	            .max();
1095	        if (maxHouseholdLevel.isEmpty()) {
1096	            return derivedLevel;
1097	        }
1098	        return Math.min(derivedLevel, maxHouseholdLevel.getAsInt() + 1);
1099	    }
1100	
1101	    /**
1102	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
1103	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
1104	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
1105	     * shares both automatically shares the same household id, so the household is keyed on
1106	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
1107	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
1108	     * still land in the same household.
1109	     *
1110	     * @param lastName the owner's last name
1111	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
1112	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
1113	     *         to no postcode-keyed household
1114	     */
1115	    private String computeHouseholdId(String lastName, String postcode) {
1116	        if (postcode == null) {
1117	            return null;
1118	        }
1119	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
1120	    }
1121	
1122	    /**
1123	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
1124	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
1125	     * the result is lower-cased.
1126	     *
1127	     * @param value the value to normalize, possibly {@code null}
1128	     * @return the normalized value, or an empty string if {@code value} is {@code null}
1129	     */
1130	    private String normalizeForComparison(String value) {
1131	        if (value == null) {
1132	            return "";
1133	        }
1134	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1135	    }
1136	
1137	    /**
1138	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
1139	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
1140	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
1141	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
1142	     * This normalized value is what gets stored and returned.
1143	     *
1144	     * @param address the raw address value submitted by the client, possibly {@code null}
1145	     * @return the normalized address, or an empty string if {@code address} is {@code null}
1146	     */
1147	    private String normalizeAddress(String address) {
1148	        if (address == null) {
1149	            return "";
1150	        }
1151	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
1152	        if (collapsed.isEmpty()) {
1153	            return collapsed;
1154	        }
1155	        String[] tokens = collapsed.split(" ");
1156	        StringBuilder normalized = new StringBuilder(collapsed.length());
1157	        for (int i = 0; i < tokens.length; i++) {
1158	            if (i > 0) {
1159	                normalized.append(' ');
1160	            }
1161	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1162	        }
1163	        return normalized.toString();
1164	    }
1165	
1166	    /**
1167	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
1168	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
1169	     * preferred when present, but either satisfies the address requirement, keeping the create
1170	     * contract backward-compatible with earlier flat-address-only owners.
1171	     *
1172	     * @param ownerFieldsDto the submitted owner fields
1173	     * @return {@code true} if an address is supplied in either form
1174	     */
1175	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
1176	        return !isBlank(ownerFieldsDto.getAddressLine1())
1177	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
1178	    }
1179	
1180	    /**
1181	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
1182	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
1183	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
1184	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
1185	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
1186	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
1187	     * working while letting everything that reads the address use the composed, normalized value.
1188	     *
1189	     * @param owner          the owner being created
1190	     * @param ownerFieldsDto the submitted owner fields
1191	     */
1192	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
1193	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
1194	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
1195	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
1196	                ? null
1197	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
1198	            owner.setAddressLine1(line1);
1199	            owner.setAddressLine2(line2);
1200	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
1201	        } else {
1202	            owner.setAddressLine1(null);
1203	            owner.setAddressLine2(null);
1204	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
1205	        }
1206	    }
1207	}
